class Solution {
public:
    bool sumGame(string num) {
        int n = num.size();
        int half = n / 2;
        long long diff = 0;
        int q = 0;
        for (int i = 0; i < n; i++) {
            if (num[i] == '?') {
                q += (i < half) ? 1 : -1;
            } else {
                int d = num[i] - '0';
                diff += (i < half) ? d : -d;
            }
        }
        if ((q & 1) != 0) return true;
        return diff != -9LL * q / 2;
    }
};
